// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for M15: HAR and curl specs, templates, replay, stale signature, TLS-bypass refusal
// Flo: parse specs > replay against the mock API > assert stored record, typed errors, no network on refusal
// I/O: mock server > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const spec = @import("pa-spec-read.zig"); const repl = @import("ct-spec-repl.zig"); const rigz = @import("te-brow-rig.zig");
const allo = std.testing.allocator;
const HAR = "{\"log\":{\"entries\":[{\"request\":{\"method\":\"GET\",\"url\":\"http://h.test/specapi?page={page}&sig=abc\",\"headers\":[{\"name\":\":authority\",\"value\":\"h.test\"},{\"name\":\"Host\",\"value\":\"h.test\"},{\"name\":\"X-Sig\",\"value\":\"good123\"},{\"name\":\"Accept-Encoding\",\"value\":\"gzip\"}]}}]}}";
const CURL = "curl 'http://h.test/specpost' \\\n  -H 'X-Sig: good123' \\\n  -H $'Content-Type: application/json' \\\n  -b 'sid=1' --compressed \\\n  --data-raw '{\"q\":\"{term}\"}'";
test "HAR: method, url, filtered headers" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const spcz = try spec.specRead(aren.allocator(), HAR); try std.testing.expectEqualStrings("GET", spcz.meth); try std.testing.expectEqual(@as(usize, 1), spcz.hdrs.len); try std.testing.expectEqualStrings("X-Sig", spcz.hdrs[0].name); }
test "curl: continuation lines, ansi quotes, cookie, data makes POST" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const spcz = try spec.specRead(aren.allocator(), CURL); try std.testing.expectEqualStrings("POST", spcz.meth); try std.testing.expectEqualStrings("http://h.test/specpost", spcz.urlz); try std.testing.expectEqualStrings("{\"q\":\"{term}\"}", spcz.body); var cook = false; for (spcz.hdrs) |hdzz| { if (std.mem.eql(u8, hdzz.name, "Cookie")) cook = true; } try std.testing.expect(cook); try std.testing.expectEqual(@as(usize, 3), spcz.hdrs.len); }
test "templates: params fill, JSON braces stay, missing param is BadSpec" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const spcz = try spec.specFill(aren.allocator(), try spec.specRead(aren.allocator(), CURL), "term=widgets&page=2"); try std.testing.expectEqualStrings("{\"q\":\"widgets\"}", spcz.body); try std.testing.expectError(error.BadSpec, spec.specFill(aren.allocator(), try spec.specRead(aren.allocator(), HAR), "other=1")); }
test "garbage and empty specs are BadSpec" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expectError(error.BadSpec, spec.specRead(aren.allocator(), "hello world")); try std.testing.expectError(error.BadSpec, spec.specRead(aren.allocator(), "")); try std.testing.expectError(error.BadSpec, spec.specRead(aren.allocator(), "{\"log\":{}}")); try std.testing.expectError(error.BadSpec, spec.specRead(aren.allocator(), "curl")); }
test "TLS bypass flags and insecure captures are refused" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expectError(error.PinBypass, spec.specRead(aren.allocator(), "curl -k 'http://h.test/a'")); try std.testing.expectError(error.PinBypass, spec.specRead(aren.allocator(), "curl --insecure 'http://h.test/a'")); try std.testing.expectError(error.PinBypass, spec.specRead(aren.allocator(), "curl --pinnedpubkey sha256//x 'http://h.test/a'")); try std.testing.expectError(error.PinBypass, spec.specRead(aren.allocator(), "{\"log\":{\"entries\":[{\"_securityState\":\"insecure\",\"request\":{\"method\":\"GET\",\"url\":\"http://h.test/\"}}]}}")); }
test "secret query values are hidden from the stored URL, page numbers stay" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got2 = try spec.urlzSafe(aren.allocator(), "http://h.test/a?page=2&sig=abc&token=zzz&q=x"); try std.testing.expectEqualStrings("http://h.test/a?page=2&q=x", got2); }
fn urlzOfzz(rig3: *rigz.Rigg, aren: std.mem.Allocator, harz: bool) ![]const u8 { var buf4: [64]u8 = undefined; const base = rig3.srv2.urlzOfzz(&buf4, ""); if (harz) return std.fmt.allocPrint(aren, "{{\"log\":{{\"entries\":[{{\"request\":{{\"method\":\"GET\",\"url\":\"{s}/specapi?page={{page}}&sig=abc\",\"headers\":[{{\"name\":\"X-Sig\",\"value\":\"{s}\"}}]}}}}]}}}}", .{ base, "good123" }); return std.fmt.allocPrint(aren, "curl '{s}/specpost' -H 'X-Sig: good123' --data-raw '{{\"q\":\"{{term}}\"}}'", .{base}); }
test "replay: signed header from the spec works, record stored under a secret-free URL" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); const aren = rig3.aren.allocator(); const tex2 = try urlzOfzz(&rig3, aren, true); const out2 = try repl.rep2(allo, aren, std.testing.io, rig3.ladz.conf, &rig3.dbzz, rig3.dirz, tex2, "page=2", true); try std.testing.expectEqualStrings("new", out2.stat); try std.testing.expectEqualStrings("json", out2.kind); try std.testing.expect(std.mem.indexOf(u8, out2.urlz, "sig=") == null); try std.testing.expect(std.mem.indexOf(u8, out2.urlz, "page=2") != null); var stmt = try rig3.dbzz.prep("SELECT body FROM reco WHERE urlz LIKE '%page=2%';"); defer stmt.fini(); try std.testing.expect(try stmt.step()); try std.testing.expect(std.mem.indexOf(u8, stmt.colzText(0), "\"query\":\"/specapi?page=2&sig=abc\"") != null); const two2 = try repl.rep2(allo, aren, std.testing.io, rig3.ladz.conf, &rig3.dbzz, rig3.dirz, tex2, "page=3", true); try std.testing.expectEqualStrings("new", two2.stat); }
test "replay POST with a templated body" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); const aren = rig3.aren.allocator(); const tex2 = try urlzOfzz(&rig3, aren, false); const out2 = try repl.rep2(allo, aren, std.testing.io, rig3.ladz.conf, &rig3.dbzz, rig3.dirz, tex2, "term=widgets", true); try std.testing.expectEqualStrings("new", out2.stat); try std.testing.expectEqual(@as(u16, 200), out2.code); }
test "stale signature is a typed error and nothing is stored" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); const aren = rig3.aren.allocator(); const tex2 = try urlzOfzz(&rig3, aren, true); const stal = try std.mem.replaceOwned(u8, aren, tex2, "good123", "old999"); try std.testing.expectError(error.StaleSpec, repl.rep2(allo, aren, std.testing.io, rig3.ladz.conf, &rig3.dbzz, rig3.dirz, stal, "page=2", true)); var stmt = try rig3.dbzz.prep("SELECT count(*) FROM page;"); defer stmt.fini(); _ = try stmt.step(); try std.testing.expectEqual(@as(i64, 0), stmt.colzIntz(0)); }
test "refusals never touch the network: bypass spec, missing param, private host" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); const aren = rig3.aren.allocator(); try std.testing.expectError(error.PinBypass, repl.rep2(allo, aren, std.testing.io, rig3.ladz.conf, &rig3.dbzz, rig3.dirz, "curl -k 'http://127.0.0.1/x'", "", true)); const tex2 = try urlzOfzz(&rig3, aren, true); try std.testing.expectError(error.BadSpec, repl.rep2(allo, aren, std.testing.io, rig3.ladz.conf, &rig3.dbzz, rig3.dirz, tex2, "", true)); try std.testing.expectError(error.BlockedHost, repl.rep2(allo, aren, std.testing.io, rig3.ladz.conf, &rig3.dbzz, rig3.dirz, tex2, "page=2", false)); try std.testing.expectEqual(@as(u32, 0), rig3.srv2.hits.load(.monotonic)); }
